def lamb(ri, ci, N, theta):
    def index(tag):
        if tag == "x_star":
            return -1
        if tag in ("z_0", "x_0"):
            return 0
        return int(tag.split("_")[1])
    i, j = index(ri), index(ci)
    if i == -1 and 0 <= j < N:
        return 2 * theta[j] / theta[N]**2
    if i == -1 and j == N:
        return 1 / theta[N]
    if 0 <= i < N and j == i + 1:
        return 2 * theta[i]**2 / theta[N]**2
    return 0

